import{_ as l,o as i,c as t,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-10-08 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-10-08 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-10-08T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","RocksDB","Blue Store","Performance Testing","Storage Engine"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-08_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-10-08_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-10-08_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function r(s,e,_,n,C,a){return i(),t("div",null,[...e[0]||(e[0]=[p("<p>本次会议主要讨论了Ceph存储引擎的相关优化和移植工作，涵盖了以下关键议题：</p><p><strong>1. RocksDB和Blue Store移植</strong></p><ul><li>[姓名]正在测试RocksDB的移植版本，性能表现良好。</li><li>[姓名]正在将Blue Store移植到Ceph存储引擎中，但遇到了一些问题，需要进一步研究。</li></ul><p><strong>2. Ceph存储引擎优化</strong></p><ul><li>[姓名]正在优化Ceph存储引擎的性能，包括： <ul><li>使用随机读取而不是顺序读取进行性能测试。</li><li>开发用于Ceph存储引擎的watchdog功能。</li><li>优化Ceph存储引擎的调试功能。</li></ul></li><li>[姓名]正在研究如何将Ceph存储引擎的性能测试自动化。</li></ul><p><strong>3. Ceph存储引擎安全</strong></p><ul><li>[姓名]正在测试Ceph存储引擎的安全性，包括： <ul><li>检查单元测试中是否存在遗漏的测试用例。</li><li>修复Ceph存储引擎中的一些安全问题。</li></ul></li></ul><p><strong>4. Ceph存储引擎兼容性</strong></p><ul><li>[姓名]正在测试Ceph存储引擎的兼容性，包括： <ul><li>将Ceph存储引擎的配置文件迁移到新的配置框架。</li><li>修复Ceph存储引擎中的一些兼容性问题。</li></ul></li></ul><p><strong>5. Ceph存储引擎架构设计</strong></p><ul><li>[姓名]正在研究Ceph存储引擎的架构设计，包括： <ul><li>设计Ceph存储引擎的插件架构。</li><li>研究Ceph存储引擎如何支持不同的硬件平台。</li><li>研究Ceph存储引擎如何支持不同的工作负载。</li></ul></li></ul><p><strong>6. Ceph存储引擎文档</strong></p><ul><li>[姓名]正在编写Ceph存储引擎的文档，包括： <ul><li>编写Ceph存储引擎的API文档。</li><li>编写Ceph存储引擎的配置文档。</li><li>编写Ceph存储引擎的故障排除文档。</li></ul></li></ul><p>会议决定继续推进RocksDB和Blue Store的移植工作，继续优化Ceph存储引擎的性能，测试其安全性、兼容性和文档，并设计Ceph存储引擎的插件架构。</p><p>行动计划包括：</p><ul><li>[姓名]将在月底前完成RocksDB移植版本的PR。</li><li>[姓名]将在月底前完成Ceph存储引擎性能测试的自动化。</li><li>[姓名]将在月底前完成Ceph存储引擎安全测试的PR。</li><li>[姓名]将在月底前完成Ceph存储引擎兼容性测试的PR。</li><li>[姓名]将在月底前完成Ceph存储引擎文档的PR。</li></ul><p>此外，[姓名]将参加Ceph存储引擎的培训，[姓名]将参加Ceph社区的会议。</p>",17)])])}const S=l(o,[["render",r]]);export{u as __pageData,S as default};
